try {
  var t = $('When Called by WF-C2').first().json || {};
  var args = t.toolInput || {};

  var msg = args.message ? String(args.message).trim() : '';
  if (!msg) { msg = 'Customer asked to speak to a member of the team. No further detail was captured.'; }

  var name = args.name ? String(args.name).trim() : '';

  var urgency = args.urgency ? String(args.urgency).toLowerCase().trim() : 'normal';
  if (urgency !== 'urgent' && urgency !== 'low') { urgency = 'normal'; }

  return [{ json: {
    phone: t.phone || '',
    name: name,
    message: msg,
    urgency: urgency,
    timestamp: new Date().toISOString(),
    toolUseId: t.toolUseId || ''
  } }];
} catch (e) {
  var fp = '';
  var fid = '';
  try { fp = $('When Called by WF-C2').first().json.phone || ''; } catch (x) {}
  try { fid = $('When Called by WF-C2').first().json.toolUseId || ''; } catch (x) {}
  return [{ json: {
    phone: fp,
    name: '',
    message: 'Customer asked to speak to a member of the team. Details could not be captured due to a system error.',
    urgency: 'normal',
    timestamp: new Date().toISOString(),
    toolUseId: fid,
    prepError: e.message
  } }];
}

try {
  var res = $input.first() ? ($input.first().json || {}) : {};
  var prep = $('Prepare Message').first().json || {};
  var toolUseId = prep.toolUseId || '';

  // BUG-R4 / R18 rule: the append runs with onError=continueRegularOutput, so a failure
  // arrives here as DATA. Google's values:append returns updates.updatedRows on success.
  // Anything else — an error body, an empty object, a 0 — means nothing was written.
  var saved = !!(res && res.updates && res.updates.updatedRows && res.updates.updatedRows > 0);

  if (!saved) {
    return [{ json: { toolCallId: toolUseId, result: 'MESSAGE NOT SAVED. A system error stopped it being recorded. Tell the customer you could not take the message down and ask them to call the office directly on the number in your business knowledge. Do NOT tell them the message has been passed on.' } }];
  }

  var line;
  if (prep.urgency === 'urgent') {
    line = 'MESSAGE SAVED and flagged URGENT. Tell the customer it has gone to the team as a priority and someone will get back to them as soon as possible. Do not promise a specific time or a specific person.';
  } else if (prep.urgency === 'low') {
    // Low urgency covers recruitment and other non-customer enquiries, where the
    // prompt explicitly forbids promising a timeline. Do not offer one here either.
    line = 'MESSAGE SAVED. Tell the customer their details have been passed to the team. Do NOT promise a callback, a timeline or a specific person for this one.';
  } else {
    line = 'MESSAGE SAVED. Tell the customer their message has been passed to the team and someone will get back to them within one working day. Do not promise a specific time or a specific person.';
  }

  return [{ json: { toolCallId: toolUseId, result: line } }];
} catch (e) {
  var fid = '';
  try { fid = $('When Called by WF-C2').first().json.toolUseId || ''; } catch (x) {}
  return [{ json: { toolCallId: fid, result: 'MESSAGE NOT SAVED. A system error occurred. Ask the customer to call the office directly on the number in your business knowledge. Do NOT claim the message was passed on.' } }];
}

// BUG-R34: the n8n Sheets append resolves the target row itself, so two concurrent
// writes pick the same row and one silently overwrites the other. We now POST to
// Google's values:append endpoint, which allocates the row server-side and is safe
// under concurrency. That endpoint writes POSITIONALLY, so column order matters —
// hence reading the live header row and mapping by NAME rather than hardcoding.
try {
  var prep = $('Prepare Message').first().json || {};
  var hdrResp = $input.first() ? ($input.first().json || {}) : {};

  // Documented A:F order from GOOGLE_SHEETS_SCHEMA.md. Used only if the live header
  // read failed, or came back without the columns the row is useless without.
  var fallback = ['Name', 'Phone', 'Message', 'Urgency', 'Timestamp', 'Status'];

  var headers = [];
  if (hdrResp && hdrResp.values && hdrResp.values.length > 0 && hdrResp.values[0] && hdrResp.values[0].length > 0) {
    for (var h = 0; h < hdrResp.values[0].length; h++) { headers.push(String(hdrResp.values[0][h]).trim()); }
  }
  var headersVerified = headers.length > 0;

  var criticalOk = headers.indexOf('Phone') !== -1 && headers.indexOf('Message') !== -1;
  var usedFallback = false;
  if (!headersVerified || !criticalOk) {
    headers = fallback;
    usedFallback = true;
  }

  var map = {
    'Name': prep.name || '',
    'Phone': prep.phone || '',
    'Message': prep.message || '',
    'Urgency': prep.urgency || 'normal',
    'Timestamp': prep.timestamp || new Date().toISOString(),
    'Status': 'new'
  };

  var row = [];
  for (var i = 0; i < headers.length; i++) {
    if (Object.prototype.hasOwnProperty.call(map, headers[i])) { row.push(map[headers[i]]); }
    else { row.push(''); }
  }

  return [{ json: { values: [row], headers: headers, headersVerified: headersVerified, usedFallback: usedFallback } }];
} catch (e) {
  // Never return an empty row — an empty append would report success having saved nothing.
  var p = {};
  try { p = $('Prepare Message').first().json || {}; } catch (x) {}
  return [{ json: { values: [[p.name || '', p.phone || '', p.message || '', p.urgency || 'normal', p.timestamp || new Date().toISOString(), 'new']], headers: ['Name', 'Phone', 'Message', 'Urgency', 'Timestamp', 'Status'], headersVerified: false, usedFallback: true, buildError: e.message } }];
}

